import React from 'react';
import { ArrowUpRight, Check } from 'lucide-react';
import { portfolioData } from '../../data/portfolioData';
import { useLanguage } from '../../context/LanguageContext';
import { PageWrapper } from '../../shared/components/PageWrapper';

const About = () => {
  const { language } = useLanguage();
  const profile = portfolioData.profile[language];
  const education = portfolioData.education[0][language];
  const copy = {
    fr: {
      eyebrow: 'À propos',
      title: 'Apprendre, construire, progresser.',
      intro: 'Mon parcours',
      training: 'Formation actuelle',
      strengths: 'Ma façon de travailler',
      projects: 'Ce qui me motive',
      projectsText: 'J’aime passer d’un besoin concret à une interface simple à utiliser, puis soigner ce qu’il y a derrière : les composants, les données et les détails qui rendent un produit fiable.',
      contact: 'Échanger avec moi'
    },
    en: {
      eyebrow: 'About',
      title: 'Learn, build, improve.',
      intro: 'My background',
      training: 'Current education',
      strengths: 'How I work',
      projects: 'What motivates me',
      projectsText: 'I enjoy turning a real need into an interface that is easy to use, then taking care of what sits behind it: the components, the data, and the details that make a product dependable.',
      contact: 'Get in touch'
    },
    ar: {
      eyebrow: 'نبذة عني',
      title: 'أتعلم، أبني، وأتطور.',
      intro: 'مساري',
      training: 'التكوين الحالي',
      strengths: 'طريقة عملي',
      projects: 'ما يحفزني',
      projectsText: 'أستمتع بتحويل احتياج حقيقي إلى واجهة سهلة الاستخدام، ثم الاهتمام بما وراءها: المكونات والبيانات والتفاصيل التي تجعل المنتج موثوقاً.',
      contact: 'تواصل معي'
    },
    es: {
      eyebrow: 'Sobre mí',
      title: 'Aprender, construir, avanzar.',
      intro: 'Mi trayectoria',
      training: 'Formación actual',
      strengths: 'Cómo trabajo',
      projects: 'Qué me motiva',
      projectsText: 'Me gusta convertir una necesidad real en una interfaz fácil de usar y cuidar también lo que hay detrás: los componentes, los datos y los detalles que hacen fiable un producto.',
      contact: 'Hablemos'
    }
  }[language];

  return (
    <PageWrapper>
      <header className="max-w-3xl">
        <p className="eyebrow">{copy.eyebrow}</p>
        <h1 className="display-heading mt-3 text-4xl leading-tight sm:text-5xl">{copy.title}</h1>
      </header>

      <div className="mt-12 grid gap-12 md:grid-cols-[0.8fr_1.2fr] md:gap-20">
        <aside>
          <div className="surface-card p-6">
            <p className="eyebrow">{copy.training}</p>
            <h2 className="mt-3 text-xl font-semibold">{education.title}</h2>
            <p className="mt-2 text-sm text-[var(--muted)]">{education.place}</p>
            <p className="mt-1 text-sm text-[var(--muted)]">{education.period}</p>
            <p className="mt-4 border-t border-[var(--line)] pt-4 text-sm leading-6 text-[var(--muted)]">{education.desc}</p>
          </div>
          <div className="mt-5 flex flex-wrap gap-2">
            {portfolioData.skills.slice(0, 3).map((skill) => (
              <span key={skill.name} className="rounded-full border border-[var(--line)] px-3 py-1.5 text-xs text-[var(--muted)]">
                {skill.name}
              </span>
            ))}
          </div>
        </aside>

        <div className="space-y-10">
          <section>
            <p className="eyebrow">{copy.intro}</p>
            <p className="mt-4 text-lg leading-8 text-[var(--muted)]">{profile.about}</p>
          </section>
          <section className="border-t border-[var(--line)] pt-8">
            <p className="eyebrow">{copy.projects}</p>
            <p className="mt-4 leading-7 text-[var(--muted)]">{copy.projectsText}</p>
          </section>
          <section className="border-t border-[var(--line)] pt-8">
            <p className="eyebrow">{copy.strengths}</p>
            <ul className="mt-5 grid gap-3 sm:grid-cols-2">
              {profile.softSkills.map((skill) => (
                <li key={skill} className="flex items-center gap-3 text-sm font-medium">
                  <span className="flex h-6 w-6 items-center justify-center rounded-full bg-[var(--accent-soft)] text-[var(--accent)]">
                    <Check size={14} />
                  </span>
                  {skill}
                </li>
              ))}
            </ul>
          </section>
          <a href="mailto:myousfi610@gmail.com" className="inline-flex items-center gap-2 text-sm font-semibold text-[var(--accent)] hover:underline">
            {copy.contact}
            <ArrowUpRight size={16} />
          </a>
        </div>
      </div>
    </PageWrapper>
  );
};

export default About;
